{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "Risperidone, which shares the 6-fluorobenzisoxazole-piperidine core with the query, has an absolute oral bioavailability of nearly 70% in humans, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Paliperidone, the closest retrieved analogue, has absolute oral bioavailability of 28% for the ER formulation but approximately 100% for the immediate-release form, indicating that the intrinsic oral F is high and the lower ER value is formulation/colonic-absorption related.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Melperone, a moderately similar butyrophenone antipsychotic, had an absolute oral bioavailability of 54 ± 24.2% in healthy volunteers, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Ketanserin, another moderately similar piperidine-containing drug, has an absolute oral bioavailability of about 46.8 ± 8.2% in healthy male subjects, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Lumateperone, a structurally more distant antipsychotic, has an absolute oral bioavailability of only 4.4%, providing a contradictory low-F example; its low similarity and distinct metabolic profile limit transfer to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The closest structural analogues (risperidone, paliperidone) have absolute oral bioavailability values of ~66-70% and ~28% (ER) / ~100% (IR), all above the 20% threshold; additional moderately similar drugs (melperone, ketanserin) also show F ≥ 50%. The only low-F analogue (lumateperone, 4.4%) is much less similar and has distinct metabolic liability. Therefore the query is predicted high (F ≥ 20%).",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself; prediction relies on close analogues with moderate Morgan similarity (0.45-0.47).",
    "Paliperidone's F is formulation-dependent (28% ER vs ~100% IR), so the intrinsic value for the query could vary with formulation.",
    "Low-F lumateperone demonstrates that some structurally related antipsychotics can undergo extensive first-pass metabolism, but its low similarity limits direct transfer."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

